// Permisos estilo Linux: r = 4, w = 2, x = 1
const LEER = 4, ESCRIBIR = 2, EJECUTAR = 1;

const dueno = LEER | ESCRIBIR | EJECUTAR;   // 7
const grupo = LEER | EJECUTAR;              // 5
const otros = LEER | EJECUTAR;              // 5

// Armar el modo completo: tres grupos de tres bits
const modo = (dueno << 6) | (grupo << 3) | otros;
console.log(modo.toString(8), modo.toString(2), modo);  // 755 111101101 493

// Preguntar por un permiso: AND con la máscara
const puede = (permiso, bit) => (permiso & bit) !== 0;
console.log(puede(grupo, ESCRIBIR));   // false
console.log(puede(dueno, ESCRIBIR));   // true

// Separar los tres grupos del modo: desplazar y enmascarar con 7 (0b111)
console.log((modo >> 6) & 7, (modo >> 3) & 7, modo & 7);  // 7 5 5

// Pasarlo a letras
const letras = p => (p & 4 ? "r" : "-") + (p & 2 ? "w" : "-") + (p & 1 ? "x" : "-");
console.log(letras(7) + letras(5) + letras(5));  // rwxr-xr-x

// La máscara de creación (umask 022) apaga bits a los permisos de un archivo nuevo
console.log((0o666 & ~0o022).toString(8));       // 644

// Desplazar a la izquierda multiplica por 2^n; a la derecha divide (sin resto)
console.log(5 << 1, 5 << 2, 5 << 3);      // 10 20 40
console.log(100 >> 1, 100 >> 2, 7 >> 1); // 50 25 3

// 1 << n es un número con SOLO el bit n encendido
console.log(1 << 3, 1 << 7, 1 << 10);     // 8 128 1024

// Leer el bit i de un número: desplazar y quedarse con el último
const bit = (n, i) => (n >> i) & 1;
console.log(bit(0b1010, 0), bit(0b1010, 1), bit(0b1010, 3));  // 0 1 1

// Par o impar: mirar solo el último bit
const esPar = n => (n & 1) === 0;
console.log([0, 1, 2, 7, 10, 255, 256].map(n => n + ":" + (esPar(n) ? "par" : "impar")).join(" "));
// 0:par 1:impar 2:par 7:impar 10:par 255:impar 256:par

// x * 10 = x * 8 + x * 2
const por10 = x => (x << 3) + (x << 1);
console.log(por10(13));                   // 130

// Un byte de estado de una camioneta (ejemplo inventado): cada bit es un sí o un no
const IGNICION = 1 << 0, PUERTA = 1 << 1, ALARMA = 1 << 2;
const m3 = n => n.toString(2).padStart(3, "0");

let estado = 0;
estado ^= IGNICION; console.log(m3(estado));  // 001  (se enciende)
estado ^= ALARMA;   console.log(m3(estado));  // 101  (suena la alarma)
estado ^= IGNICION; console.log(m3(estado));  // 100  (se apaga el motor)
estado ^= ALARMA;   console.log(m3(estado));  // 000  (se apaga la alarma)

// Encender, apagar y consultar con una máscara
estado |= PUERTA;                             // encender
console.log(m3(estado), (estado & PUERTA) !== 0);  // 010 true
estado &= ~PUERTA;                            // apagar
console.log(m3(estado), (estado & PUERTA) !== 0);  // 000 false

// XOR dos veces con la misma clave devuelve el original
const dato = 5, clave = 0b1011;
const mezclado = dato ^ clave;
console.log(mezclado, mezclado ^ clave);      // 14 5

const color = 0xE8A33D;

// Separar los canales
const r = (color >> 16) & 0xFF;
const g = (color >> 8) & 0xFF;
const b = color & 0xFF;
console.log(r, g, b);                          // 232 163 61

// Volver a armarlo
const armado = (r << 16) | (g << 8) | b;
console.log(armado.toString(16).toUpperCase());  // E8A33D

// Apagar el verde con una máscara, y después ponerlo al máximo con OR
const sinVerde = color & 0xFF00FF;
console.log(sinVerde.toString(16).toUpperCase());           // E8003D
console.log((sinVerde | 0x00FF00).toString(16).toUpperCase()); // E8FF3D

// 1) El bit 31 es el de signo
console.log(1 << 31);            // -2147483648
console.log(0xFFFFFFFF | 0);     // -1
console.log(0xFFFFFFFF >>> 0);   // 4294967295  (>>> 0 lo devuelve a positivo)

// 2) Lo que pasa de 32 bits se pierde
console.log(2 ** 32 | 0);        // 0
console.log(2 ** 40 + 5 | 0);    // 5

// 3) ~ no es el NOT de un byte
console.log(~5);                 // -6
console.log(~5 & 0xFF);          // 250

// 4) La cantidad de lugares se toma módulo 32
console.log(1 << 32, 1 << 33);   // 1 2

// 5) >> conserva el signo; >>> rellena con ceros
console.log(0xFF000000 >> 24);   // -1
console.log(0xFF000000 >>> 24);  // 255
console.log(-7 >> 1);            // -4  (redondea hacia abajo; -7 / 2 sería -3,5)

// 6) Los decimales se truncan y lo que no es número da 0
console.log(5.9 | 0, -5.9 | 0, NaN | 0);   // 5 -5 0

// 7) La precedencia juega en contra: === pesa más que &
console.log(6 & 1 === 0);        // 0  (se lee 6 & (1 === 0))
console.log((6 & 1) === 0);      // true

// Para más de 32 bits: BigInt
console.log(1n << 40n);          // 1099511627776n
